+            if (getOldClusterVersion().before(Version.V_8_0_0)) {
+                bulk.setOptions(expectWarnings(EXPECTED_WARNING));
+            }
+            bulk.setJsonEntity(Strings.format("""
+                {"index": {"_index": "%s"}}
+                {"f1": "v3", "f2": "v4"}
+                """, INDEX_NAME));
